package com.library.model;

/**
 * Entity representing an access history log for digital journals.
 * personId is nullable (NULL for anonymous Guest).
 * ipAddress is a synthetic random IP generated by sp_access_digital_journal.
 */
public class AccessLog {
    private long logId;
    private Integer personId;
    private int journalResourceId;
    private String ipAddress;

    public AccessLog() {
    }

    public AccessLog(long logId, Integer personId, int journalResourceId, String ipAddress) {
        this.logId = logId;
        this.personId = personId;
        this.journalResourceId = journalResourceId;
        this.ipAddress = ipAddress;
    }

    public long getLogId() {
        return logId;
    }

    public void setLogId(long logId) {
        this.logId = logId;
    }

    public Integer getPersonId() {
        return personId;
    }

    public void setPersonId(Integer personId) {
        this.personId = personId;
    }

    public int getJournalResourceId() {
        return journalResourceId;
    }

    public void setJournalResourceId(int journalResourceId) {
        this.journalResourceId = journalResourceId;
    }

    public String getIpAddress() {
        return ipAddress;
    }

    public void setIpAddress(String ipAddress) {
        this.ipAddress = ipAddress;
    }

    @Override
    public String toString() {
        return "AccessLog{" +
                "logId=" + logId +
                ", personId=" + personId +
                ", journalResourceId=" + journalResourceId +
                ", ipAddress='" + ipAddress + '\'' +
                '}';
    }
}
